class Solution {
    public int maxScore(int[] nums) {
        int m = nums.length;
        int[][] gcd = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                gcd[i][j] = getGCD(nums[i], nums[j]);
            }
        }

        int totalMasks = 1 << m;
        int[] dp = new int[totalMasks];

        for (int mask = 0; mask < totalMasks; mask++) {
            int count = Integer.bitCount(mask);
            if (count % 2 != 0) continue;

            int op = count / 2 + 1;

            // Find the first unset bit to avoid redundant transitions
            int first = -1;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) == 0) {
                    first = i;
                    break;
                }
            }

            if (first == -1) continue;

            for (int second = first + 1; second < m; second++) {
                if ((mask & (1 << second)) == 0) {
                    int nextMask = mask | (1 << first) | (1 << second);
                    int score = dp[mask] + op * gcd[first][second];
                    if (score > dp[nextMask]) {
                        dp[nextMask] = score;
                    }
                }
            }
        }

        return dp[totalMasks - 1];
    }

    private int getGCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
