import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        String digits = s.substring(1, s.length() - 1);
        int n = digits.length();

        for (int i = 1; i < n; i++) {
            List<String> left = getValid(digits.substring(0, i));
            List<String> right = getValid(digits.substring(i));

            for (String l : left) {
                for (String r : right) {
                    result.add("(" + l + ", " + r + ")");
                }
            }
        }

        return result;
    }

    private List<String> getValid(String t) {
        List<String> list = new ArrayList<>();
        int len = t.length();

        // Without decimal point
        if (len == 1 || t.charAt(0) != '0') {
            list.add(t);
        }

        // With decimal point
        for (int d = 1; d < len; d++) {
            String integerPart = t.substring(0, d);
            String fractionalPart = t.substring(d);

            boolean validInteger = (d == 1 || integerPart.charAt(0) != '0');
            boolean validFractional = !fractionalPart.endsWith("0");

            if (validInteger && validFractional) {
                list.add(integerPart + "." + fractionalPart);
            }
        }

        return list;
    }
}
