class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int[] freqCount = new int[12];
        for (String word : words) {
            freqCount[f(word)]++;
        }

        for (int i = 9; i >= 0; i--) {
            freqCount[i] += freqCount[i + 1];
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = freqCount[f(queries[i]) + 1];
        }

        return ans;
    }

    private int f(String s) {
        char minChar = 'z';
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < minChar) {
                minChar = c;
                count = 1;
            } else if (c == minChar) {
                count++;
            }
        }
        return count;
    }
}
