class Solution {
    private int[] memo;
    private int[] pow3;
    private int[] nums;
    private int numSlots;

    public int maximumANDSum(int[] nums, int numSlots) {
        this.nums = nums;
        this.numSlots = numSlots;

        pow3 = new int[numSlots + 1];
        pow3[0] = 1;
        for (int i = 1; i <= numSlots; i++) {
            pow3[i] = pow3[i - 1] * 3;
        }

        memo = new int[pow3[numSlots]];
        java.util.Arrays.fill(memo, -1);

        return dfs(0, 0);
    }

    private int dfs(int mask, int index) {
        if (index == nums.length) {
            return 0;
        }
        if (memo[mask] != -1) {
            return memo[mask];
        }

        int maxVal = 0;
        for (int slot = 0; slot < numSlots; slot++) {
            int count = (mask / pow3[slot]) % 3;
            if (count < 2) {
                int andVal = nums[index] & (slot + 1);
                maxVal = Math.max(maxVal, andVal + dfs(mask + pow3[slot], index + 1));
            }
        }

        return memo[mask] = maxVal;
    }
}
