    public int maxEqualFreq(int[] nums) {
        int[] count = new int[100001];
        int[] freq = new int[100001];
        int maxF = 0;
        int ans = 0;

        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (count[x] > 0) {
                freq[count[x]]--;
            }
            count[x]++;
            freq[count[x]]++;
