import java.util.Arrays;

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int totalStates = 1 << n;

        int[] dpSessions = new int[totalStates];
        int[] dpTime = new int[totalStates];

        Arrays.fill(dpSessions, Integer.MAX_VALUE);
        Arrays.fill(dpTime, Integer.MAX_VALUE);

        dpSessions[0] = 1;
        dpTime[0] = 0;

        for (int mask = 0; mask < totalStates; mask++) {
            if (dpSessions[mask] == Integer.MAX_VALUE) continue;

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    int nextMask = mask | (1 << i);
                    int newSessions = dpSessions[mask];
                    int newTime;

                    if (dpTime[mask] + tasks[i] <= sessionTime) {
                        newTime = dpTime[mask] + tasks[i];
                    } else {
                        newSessions++;
                        newTime = tasks[i];
                    }

                    if (newSessions < dpSessions[nextMask] || 
                       (newSessions == dpSessions[nextMask] && newTime < dpTime[nextMask])) {
                        dpSessions[nextMask] = newSessions;
                        dpTime[nextMask] = newTime;
                    }
                }
            }
        }

        return dpSessions[totalStates - 1];
    }
}
