        int[] result = new int[n];
        Arrays.fill(result, -1);

        int[] stack = new int[n];
        int top = -1;

        for (int i = 0; i < 2 * n; i++) {
            int num = nums[i % n];
            while (top >= 0 && nums[stack[top]] < num) {
                result[stack[top--]] = num;
