import java.util.Arrays;

class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        return count(nums1, nums2) + count(nums2, nums1);
    }

    private int count(int[] a, int[] b) {
        int[] sortedB = b.clone();
        Arrays.sort(sortedB);
        int totalWays = 0;

        for (int x : a) {
            long target = (long) x * x;
            int l = 0, r = sortedB.length - 1;

            while (l < r) {
                long prod = (long) sortedB[l] * sortedB[r];
                if (prod < target) {
                    l++;
                } else if (prod > target) {
                    r--;
                } else {
                    if (sortedB[l] == sortedB[r]) {
                        int count = r - l + 1;
                        totalWays += count * (count - 1) / 2;
                        break;
                    } else {
                        int leftVal = sortedB[l];
                        int c1 = 0;
                        while (l < r && sortedB[l] == leftVal) {
                            c1++;
                            l++;
                        }
                        int rightVal = sortedB[r];
                        int c2 = 0;
                        while (l <= r && sortedB[r] == rightVal) {
                            c2++;
                            r--;
                        }
                        totalWays += c1 * c2;
                    }
                }
            }
        }

        return totalWays;
    }
