class Solution {
    public int maxSizeSlices(int[] slices) {
        int n = slices.length / 3;
        int[] slices1 = new int[slices.length - 1];
        int[] slices2 = new int[slices.length - 1];

        System.arraycopy(slices, 0, slices1, 0, slices.length - 1);
        System.arraycopy(slices, 1, slices2, 0, slices.length - 1);

        return Math.max(maxSum(slices1, n), maxSum(slices2, n));
    }

    private int maxSum(int[] arr, int k) {
        int m = arr.length;
        int[][] dp = new int[m + 1][k + 1];

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= k; j++) {
                int take = arr[i - 1] + (i >= 2 ? dp[i - 2][j - 1] : 0);
                int notTake = dp[i - 1][j];
                dp[i][j] = Math.max(take, notTake);
            }
        }

        return dp[m][k];
    }
}
