class Solution {
    public int[] restoreArray(int[][] adjacentPairs) {
        int n = adjacentPairs.length + 1;
        int OFFSET = 100000;
        int[][] adj = new int[200005][2];
        int[] deg = new int[200005];

        for (int[] pair : adjacentPairs) {
            int u = pair[0] + OFFSET;
            int v = pair[1] + OFFSET;
            adj[u][deg[u]++] = pair[1];
            adj[v][deg[v]++] = pair[0];
        }

        int start = 0;
        for (int i = 0; i <= 200000; i++) {
            if (deg[i] == 1) {
                start = i - OFFSET;
                break;
            }
        }

        int[] result = new int[n];
        result[0] = start;
        result[1] = adj[start + OFFSET][0];

        for (int i = 2; i < n; i++) {
            int prev = result[i - 1] + OFFSET;
            result[i] = (adj[prev][0] == result[i - 2]) ? adj[prev][1] : adj[prev][0];
        }

        return result;
    }
