        int d = 0;
        int step = 1;

        while (idx < total) {
            for (int i = 0; i < step; i++) {
                r += dirs[d][0];
                c += dirs[d][1];
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    res[idx++] = new int[]{r, c};
                    if (idx == total) {
                        return res;
                    }
