class StreamChecker {

    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isEnd = false;
    }

    private final TrieNode root = new TrieNode();
    private final char[] history;
    private final int maxLen;
    private int head = 0;
    private int total = 0;

    public StreamChecker(String[] words) {
        int longest = 0;
        for (String w : words) {
            longest = Math.max(longest, w.length());
            TrieNode curr = root;
            for (int i = w.length() - 1; i >= 0; i--) {
                int c = w.charAt(i) - 'a';
                if (curr.children[c] == null) {
                    curr.children[c] = new TrieNode();
                }
                curr = curr.children[c];
            }
            curr.isEnd = true;
        }
        this.maxLen = longest;
        this.history = new char[maxLen];
    }

    public boolean query(char letter) {
        history[head] = letter;
        head = (head + 1) % maxLen;
        if (total < maxLen) {
            total++;
        }

        TrieNode curr = root;
        for (int i = 0; i < total; i++) {
            int idx = (head - 1 - i + maxLen) % maxLen;
            int c = history[idx] - 'a';
            if (curr.children[c] == null) {
                return false;
            }
            curr = curr.children[c];
            if (curr.isEnd) {
                return true;
            }
        }
        return false;
    }
}

